class Solution {

    public List<String> restoreIpAddresses(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        if(n < 4 || n> 12) return res;

        f(res, 0, new ArrayList<>(), s);

        return res;
    }

    public void f(List<String> res, int begin, List<String> curr, String s){
        if(curr.size() == 4 && begin == s.length()){
            res.add(String.join(".", curr));
            return ;
        }
        if(curr.size() > 4 || begin > s.length()){
            return ;
        }

        for(int i=1; i<=3; i++){
            int end = begin+i;
            if(end > s.length()) break;
            String segment = s.substring(begin, end);
            if(segment.length() > 1 && segment.startsWith("0")) continue;
            if(Integer.parseInt(segment) > 255) continue;
            curr.add(segment);
            f(res, end, curr, s);
            curr.remove(curr.size()-1);
        }
    }
}
